def main():
    out = Path(__file__).parent / "handwritten.jsonl"
    with open(out, "w") as f:
        for i, (q, a, urls, hop) in enumerate(Q, 1):
            js_only = all(u.startswith((GE, DS)) for u in urls)
            f.write(json.dumps({"id": f"h{i:03d}", "question": q, "reference": a, "gold_urls": urls,
                                "hop": hop, "js_only": js_only, "source": "handwritten"}) + "\n")
    print(f"{len(Q)} questions -> {out}")


if __name__ == "__main__":
    main()
